create table public.event_promotion_drafts (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),display_name text not null check(length(trim(display_name)) between 1 and 60),event_type text not null check(event_type in ('Wedding','Birthday','Anniversary','Graduation','Baby shower','Celebration of life','Special celebration')),event_date date not null,chosen_location text not null check(length(trim(chosen_location)) between 1 and 120),weekly_price_cents integer not null default 2995 check(weekly_price_cents=2995),created_at timestamptz not null default now()); alter table public.event_promotion_drafts enable row level security; revoke all on public.event_promotion_drafts from anon,authenticated; grant select on public.event_promotion_drafts to authenticated; grant insert(user_id,display_name,event_type,event_date,chosen_location) on public.event_promotion_drafts to authenticated; grant all on public.event_promotion_drafts to service_role; create policy promotion_draft_own_read on public.event_promotion_drafts for select to authenticated using(user_id=(select auth.uid())); create policy promotion_draft_own_insert on public.event_promotion_drafts for insert to authenticated with check(user_id=(select auth.uid())); create index event_promotion_drafts_user_idx on public.event_promotion_drafts(user_id);